class MemoriError(Exception):
    def __init__(self, message: str, error_code: str | None=None, context: dict[str, Any] | None=None, cause: Exception | None=None):
        super().__init__(message)
        self.message = message
        self.error_code = error_code or self.__class__.__name__.upper()
        self.context = context or {}
        self.cause = cause
        self.timestamp = datetime.now()
        self.traceback = traceback.format_exc() if cause else None
    def to_dict(self) -> dict[str, Any]:
        return {'error_type': self.__class__.__name__, 'error_code': self.error_code, 'message': self.message, 'context': self.context, 'timestamp': self.timestamp.isoformat(), 'cause': str(self.cause) if self.cause else None, 'traceback': self.traceback}
    def __str__(self) -> str:
        base_msg = f'[{self.error_code}] {self.message}'
        if self.context:
            base_msg += f' | Context: {self.context}'
        if self.cause:
            base_msg += f' | Caused by: {self.cause}'
        return base_msg
class DatabaseError(MemoriError):
    def __init__(self, message: str, query: str | None=None, connection_string: str | None=None, error_code: str | None=None, cause: Exception | None=None):
        context = {}
        if query:
            context['query'] = query
        if connection_string:
            sanitized = self._sanitize_connection_string(connection_string)
            context['connection'] = sanitized
        super().__init__(message=message, error_code=error_code or 'DB_ERROR', context=context, cause=cause)
    @staticmethod\
    def _sanitize_connection_string(conn_str: str) -> str:
        import re
        sanitized = re.sub('://[^:]+:[^@]+@', '://***:***@', conn_str)
        return sanitized
