from typing import Any
from loguru import logger
class LoggingManager:
    _initialized = False
    _current_config: LoggingSettings | None = None
    @classmethod
    def setup_logging(cls, settings: LoggingSettings, verbose: bool=False) -> None:
        try:
            if not cls._initialized:
                logger.remove()
            if verbose:
                cls._disable_other_loggers()
                logger.add(sys.stderr, level='DEBUG', format='<green>{time:HH:mm:ss}</green> | <level>{level:8}</level> | {message}', colorize=True, backtrace=True, diagnose=True)
            else:
                logger.add(sys.stderr, level='WARNING', format='<level>{level}</level>: {message}', colorize=False, backtrace=False, diagnose=False)
            if settings.log_to_file:
                log_path = Path(settings.log_file_path)
                log_path.parent.mkdir(parents=True, exist_ok=True)
                if settings.structured_logging:
                    logger.add(log_path, level=settings.level.value, format='{time:YYYY-MM-DD HH:mm:ss.SSS} | {level} | {name}:{function}:{line} | {message}', rotation=settings.log_rotation, retention=settings.log_retention, compression=settings.log_compression, serialize=True)
                else:
                    logger.add(log_path, level=settings.level.value, format=settings.format, rotation=settings.log_rotation, retention=settings.log_retention, compression=settings.log_compression)
            cls._initialized = True
            cls._current_config = settings
            logger.info('Logging configuration initialized')
        except Exception as e:
            raise ConfigurationError(f'Failed to setup logging: {e}') from e
    @classmethod
    def get_logger(cls, name: str) -> 'logger':
        return logger.bind(name=name)
    @classmethod
    def update_log_level(cls, level: LogLevel) -> None:
        if not cls._initialized:
            raise ConfigurationError('Logging not initialized')
        try:
            logger.remove()
            if cls._current_config:
                cls._current_config.level = level
                cls.setup_logging(cls._current_config)
        except Exception as e:
            logger.error(f'Failed to update log level: {e}')
    @classmethod
    def add_custom_handler(cls, handler_config: dict[str, Any]) -> None:
        try:
            logger.add(**handler_config)
            logger.debug(f'Added custom logging handler: {handler_config}')
        except Exception as e:
            logger.error(f'Failed to add custom handler: {e}')
    @classmethod
    def is_initialized(cls) -> bool:
        return cls._initialized
    @classmethod
    def get_current_config(cls) -> LoggingSettings | None:
        return cls._current_config
    @classmethod
    def _disable_other_loggers(cls) -> None:
        class InterceptStandardLoggingHandler(logging.Handler):
            def emit(self, record: logging.LogRecord) -> None:
                try:
                    level = logger.level(record.levelname).name
                except ValueError:
                    level = record.levelno
                frame, depth = (logging.currentframe(), 2)
                while frame is not None and frame.f_code.co_filename == logging.__file__:
                    frame = frame.f_back
                    depth += 1
                formatted_message = f'[{record.name}] {record.getMessage()}'
                logger.opt(depth=depth, exception=record.exc_info).log(level, formatted_message)
        logging.basicConfig(handlers=[InterceptStandardLoggingHandler()], level=0, force=True)
def get_logger(name: str='memori') -> 'logger':
    return LoggingManager.get_logger(name)
