        elif float_score > 1.0:
            return 1.0
        return float_score
    @classmethod
    def validate_boolean_field(cls, value: Any, field_name: str='field') -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return bool(value)
        if isinstance(value, str):
            return value.lower() in ('true', '1', 'yes', 'on')
        return False
