        sanitized = re.sub('[^a-zA-Z0-9_]', '', identifier)
        if not sanitized or not re.match('^[a-zA-Z][a-zA-Z0-9_]*$', sanitized):
            raise ValidationError('Invalid SQL identifier format')
        if len(sanitized) > 64:
            raise ValidationError('SQL identifier too long')
        reserved_words = {'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'DROP', 'CREATE', 'ALTER', 'TABLE', 'DATABASE', 'INDEX', 'VIEW', 'TRIGGER', 'PROCEDURE', 'FUNCTION', 'EXEC', 'EXECUTE', 'UNION', 'WHERE', 'FROM', 'JOIN'}
