            raise SecurityError(message=f'{func.__name__} requires a non-empty user_id string', security_check='require_user_id', user_id=str(user_id), operation=func.__name__, error_code='INVALID_USER_ID')
        if user_id.strip() == 'default':
            logger.warning(f"[SECURITY] Function '{func.__name__}' called with user_id='default'. This should only be used in development/testing environments.")
        logger.debug(f"[SECURITY] Validated user_id for {func.__name__}: user_id='{user_id[:8]}...'")
        return func(*args, **kwargs)
