    def _audit_parameter_validation(self, query: str, params: list[Any] | None, context: str | None) -> list[SecurityFinding]:
        findings = []
        if params:
            for i, param in enumerate(params):
                if isinstance(param, str):
                    for pattern in self.XSS_PATTERNS:
                        if re.search(pattern, param, re.IGNORECASE):
                            findings.append(SecurityFinding(vulnerability_type=VulnerabilityType.XSS, severity=SecurityLevel.HIGH, description=f'XSS pattern in parameter {i}', location=context or 'unknown', recommendation='Sanitize and validate input parameters', evidence=f'Parameter value: {param[:100]}...'))
