                        if re.search(pattern, param):
                            findings.append(SecurityFinding(vulnerability_type=VulnerabilityType.COMMAND_INJECTION, severity=SecurityLevel.CRITICAL, description=f'Command injection pattern in parameter {i}', location=context or 'unknown', recommendation='Validate and sanitize all user input', evidence=f'Parameter value: {param[:100]}...'))
