                        if re.search(pattern, param):
                            findings.append(SecurityFinding(vulnerability_type=VulnerabilityType.PATH_TRAVERSAL, severity=SecurityLevel.HIGH, description=f'Path traversal pattern in parameter {i}', location=context or 'unknown', recommendation='Validate file paths and restrict access', evidence=f'Parameter value: {param[:100]}...'))
