        query_upper = query.upper()
        if re.search('SELECT\\s+\\*', query_upper):
            findings.append(SecurityFinding(vulnerability_type=VulnerabilityType.DATA_EXPOSURE, severity=SecurityLevel.MEDIUM, description='SELECT * query may expose unnecessary data', location=context or 'unknown', recommendation='Specify exact columns needed instead of using *', evidence='Query uses SELECT *'))
