            findings.append(SecurityFinding(vulnerability_type=VulnerabilityType.DATA_EXPOSURE, severity=SecurityLevel.CRITICAL, description='UPDATE/DELETE without WHERE clause', location=context or 'unknown', recommendation='Always include WHERE clause in UPDATE/DELETE operations', evidence='Missing WHERE clause'))
        sensitive_keywords = ['PASSWORD', 'TOKEN', 'SECRET', 'KEY', 'PRIVATE', 'SSN', 'SOCIAL_SECURITY', 'CREDIT_CARD', 'CVV']
        for keyword in sensitive_keywords:
            if keyword in query_upper:
                findings.append(SecurityFinding(vulnerability_type=VulnerabilityType.DATA_EXPOSURE, severity=SecurityLevel.HIGH, description=f'Query references potentially sensitive data: {keyword}', location=context or 'unknown', recommendation='Ensure sensitive data is properly protected and encrypted', evidence=f'Keyword: {keyword}'))
        return findings
    def validate_query_safety(self, query: str, params: list[Any] | None=None, context: str | None=None, strict_mode: bool=True) -> tuple[bool, list[SecurityFinding]]:
        findings = self.audit_query(query, params, context)
        has_critical = any((f.severity == SecurityLevel.CRITICAL for f in findings))
        has_high = any((f.severity == SecurityLevel.HIGH for f in findings))
        is_safe = True
        if strict_mode:
            is_safe = not (has_critical or has_high)
        else:
            is_safe = not has_critical
        return (is_safe, findings)
    def generate_audit_report(self) -> SecurityAuditReport:
        critical_count = sum((1 for f in self.findings if f.severity == SecurityLevel.CRITICAL))
        high_count = sum((1 for f in self.findings if f.severity == SecurityLevel.HIGH))
        medium_count = sum((1 for f in self.findings if f.severity == SecurityLevel.MEDIUM))
        low_count = sum((1 for f in self.findings if f.severity == SecurityLevel.LOW))
        risk_score = min(100, critical_count * 25 + high_count * 10 + medium_count * 5 + low_count * 1)
        return SecurityAuditReport(findings=self.findings.copy(), total_queries_audited=self.queries_audited, critical_count=critical_count, high_count=high_count, medium_count=medium_count, low_count=low_count, audit_timestamp=time.time(), overall_risk_score=risk_score)
