class SecureQueryBuilder:
    def __init__(self, auditor: DatabaseSecurityAuditor):
        self.auditor = auditor
    def build_safe_select(self, table: str, columns: list[str], where_conditions: dict[str, Any], limit: int | None=None) -> tuple[str, list[Any]]:
        table = InputValidator.sanitize_sql_identifier(table)
        validated_columns = [InputValidator.sanitize_sql_identifier(col) for col in columns]
        columns_str = ', '.join(validated_columns)
        query = f'SELECT {columns_str} FROM {table}'
        params = []
        if where_conditions:
            where_parts = []
            for column, value in where_conditions.items():
                safe_column = InputValidator.sanitize_sql_identifier(column)
                where_parts.append(f'{safe_column} = ?')
                params.append(value)
            query += f" WHERE {' AND '.join(where_parts)}"
        if limit:
            query += ' LIMIT ?'
            params.append(int(limit))
        is_safe, findings = self.auditor.validate_query_safety(query, params, 'build_safe_select')
        if not is_safe:
            raise SecurityError(f'Generated query failed security audit: {findings}')
        return (query, params)
    def build_safe_insert(self, table: str, data: dict[str, Any]) -> tuple[str, list[Any]]:
        table = InputValidator.sanitize_sql_identifier(table)
        validated_data = {}
        for column, value in data.items():
            safe_column = InputValidator.sanitize_sql_identifier(column)
            validated_data[safe_column] = value
        columns = list(validated_data.keys())
        values = list(validated_data.values())
        columns_str = ', '.join(columns)
        placeholders = ', '.join(['?'] * len(values))
        query = f'INSERT INTO {table} ({columns_str}) VALUES ({placeholders})'
        is_safe, findings = self.auditor.validate_query_safety(query, values, 'build_safe_insert')
        if not is_safe:
            raise SecurityError(f'Generated query failed security audit: {findings}')
        return (query, values)
