from enum import Enum
from typing import Any
from loguru import logger
class DatabaseDialect(str, Enum):
    SQLITE = 'sqlite'
    POSTGRESQL = 'postgresql'
    MYSQL = 'mysql'
class QueryBuilder:
    PARAM_STYLES = {DatabaseDialect.SQLITE: '?', DatabaseDialect.POSTGRESQL: '%s', DatabaseDialect.MYSQL: '%s'}
    LIMIT_SYNTAX = {DatabaseDialect.SQLITE: 'LIMIT ?', DatabaseDialect.POSTGRESQL: 'LIMIT %s', DatabaseDialect.MYSQL: 'LIMIT %s'}
    def __init__(self, dialect: DatabaseDialect):
        self.dialect = dialect
        self.param_placeholder = self.PARAM_STYLES[dialect]
    def build_search_query(self, tables: list[str], search_columns: list[str], query_text: str, namespace: str, category_filter: list[str] | None=None, limit: int=10, use_fts: bool=False) -> tuple[str, list[Any]]:
        try:
            query_text = InputValidator.validate_and_sanitize_query(query_text)
            namespace = InputValidator.validate_namespace(namespace)
            category_filter = InputValidator.validate_category_filter(category_filter)
            limit = InputValidator.validate_limit(limit)
            for table in tables:
                InputValidator.sanitize_sql_identifier(table)
            for column in search_columns:
                InputValidator.sanitize_sql_identifier(column)
        except ValidationError as e:
            raise DatabaseError(f'Invalid query parameters: {e}')
        params = []
        where_conditions = []
        if use_fts and self.dialect == DatabaseDialect.SQLITE:
            fts_condition = f'memory_search_fts MATCH {self.param_placeholder}'
            params.append(f'"{query_text}"' if query_text else '*')
            where_conditions.append(fts_condition)
        elif use_fts and self.dialect == DatabaseDialect.POSTGRESQL:
            search_conditions = []
            for column in search_columns:
                search_conditions.append(f"to_tsvector('english', {column}) @@ plainto_tsquery('english', {self.param_placeholder})")
                params.append(query_text)
            where_conditions.append(f"({' OR '.join(search_conditions)})")
        elif use_fts and self.dialect == DatabaseDialect.MYSQL:
            search_conditions = []
            for column in search_columns:
                search_conditions.append(f'MATCH({column}) AGAINST ({self.param_placeholder} IN BOOLEAN MODE)')
                params.append(query_text)
            where_conditions.append(f"({' OR '.join(search_conditions)})")
        else:
            like_conditions = []
            for column in search_columns:
                like_conditions.append(f'{column} LIKE {self.param_placeholder}')
                params.append(f'%{query_text}%')
            where_conditions.append(f"({' OR '.join(like_conditions)})")
        where_conditions.append(f'namespace = {self.param_placeholder}')
        params.append(namespace)
        if category_filter:
            placeholders = ','.join([self.param_placeholder] * len(category_filter))
            where_conditions.append(f'category_primary IN ({placeholders})')
            params.extend(category_filter)
        if len(tables) == 1:
            query = f"\n                SELECT *, '{tables[0]}' as memory_type\n                FROM {tables[0]}\n                WHERE {' AND '.join(where_conditions)}\n                ORDER BY importance_score DESC, created_at DESC\n                {self.LIMIT_SYNTAX[self.dialect]}\n            "
        else:
            union_parts = []
            for table in tables:
                table_query = f"\n                    SELECT *, '{table}' as memory_type\n                    FROM {table}\n                    WHERE {' AND '.join(where_conditions)}\n                "
                union_parts.append(table_query)
            query = f"\n                SELECT * FROM (\n                    {' UNION ALL '.join(union_parts)}\n                ) combined\n                ORDER BY importance_score DESC, created_at DESC\n                {self.LIMIT_SYNTAX[self.dialect]}\n            "
        params.append(limit)
        return (query, params)
    def build_insert_query(self, table: str, data: dict[str, Any], on_conflict: str='REPLACE') -> tuple[str, list[Any]]:
        try:
            table = InputValidator.sanitize_sql_identifier(table)
            validated_data = {}
            for key, value in data.items():
                validated_key = InputValidator.sanitize_sql_identifier(key)
                validated_data[validated_key] = value
        except ValidationError as e:
            raise DatabaseError(f'Invalid insert parameters: {e}')
        columns = list(validated_data.keys())
        values = list(validated_data.values())
        columns_str = ', '.join(columns)
        placeholders = ', '.join([self.param_placeholder] * len(values))
        if on_conflict == 'REPLACE':
            if self.dialect == DatabaseDialect.SQLITE:
                query = f'INSERT OR REPLACE INTO {table} ({columns_str}) VALUES ({placeholders})'
            elif self.dialect == DatabaseDialect.POSTGRESQL:
                primary_key = self._get_primary_key_column(columns)
                if primary_key:
                    update_clause = ', '.join([f'{col} = EXCLUDED.{col}' for col in columns if col != primary_key])
                    query = f'\n                        INSERT INTO {table} ({columns_str}) VALUES ({placeholders})\n                        ON CONFLICT ({primary_key}) DO UPDATE SET {update_clause}\n                    '
                else:
                    query = f'INSERT INTO {table} ({columns_str}) VALUES ({placeholders})'
            elif self.dialect == DatabaseDialect.MYSQL:
                update_clause = ', '.join([f'{col} = VALUES({col})' for col in columns])
                query = f'\n                    INSERT INTO {table} ({columns_str}) VALUES ({placeholders})\n                    ON DUPLICATE KEY UPDATE {update_clause}\n                '
        else:
            query = f'INSERT INTO {table} ({columns_str}) VALUES ({placeholders})'
        return (query, values)
    def build_update_query(self, table: str, data: dict[str, Any], where_conditions: dict[str, Any]) -> tuple[str, list[Any]]:
        try:
            table = InputValidator.sanitize_sql_identifier(table)
            for key in list(data.keys()) + list(where_conditions.keys()):
                InputValidator.sanitize_sql_identifier(key)
        except ValidationError as e:
            raise DatabaseError(f'Invalid update parameters: {e}')
        set_conditions = []
        params = []
        for column, value in data.items():
            set_conditions.append(f'{column} = {self.param_placeholder}')
            params.append(value)
        where_parts = []
        for column, value in where_conditions.items():
            where_parts.append(f'{column} = {self.param_placeholder}')
            params.append(value)
        query = f"\n            UPDATE {table}\n            SET {', '.join(set_conditions)}\n            WHERE {' AND '.join(where_parts)}\n        "
        return (query, params)
    def build_delete_query(self, table: str, where_conditions: dict[str, Any]) -> tuple[str, list[Any]]:
        try:
            table = InputValidator.sanitize_sql_identifier(table)
            for key in where_conditions.keys():
                InputValidator.sanitize_sql_identifier(key)
        except ValidationError as e:
            raise DatabaseError(f'Invalid delete parameters: {e}')
        where_parts = []
        params = []
        for column, value in where_conditions.items():
            where_parts.append(f'{column} = {self.param_placeholder}')
            params.append(value)
        query = f"DELETE FROM {table} WHERE {' AND '.join(where_parts)}"
        return (query, params)
    def build_fts_query(self, query_text: str, namespace: str, category_filter: list[str] | None=None, limit: int=10) -> tuple[str, list[Any]]:
        try:
            query_text = InputValidator.validate_and_sanitize_query(query_text)
            namespace = InputValidator.validate_namespace(namespace)
            category_filter = InputValidator.validate_category_filter(category_filter)
            limit = InputValidator.validate_limit(limit)
        except ValidationError as e:
            raise DatabaseError(f'Invalid FTS parameters: {e}')
        params = []
        where_conditions = []
        if self.dialect == DatabaseDialect.SQLITE:
            where_conditions.append(f'memory_search_fts MATCH {self.param_placeholder}')
            params.append(f'"{query_text}"' if query_text else '*')
            where_conditions.append(f'fts.namespace = {self.param_placeholder}')
            params.append(namespace)
            if category_filter:
                placeholders = ','.join([self.param_placeholder] * len(category_filter))
                where_conditions.append(f'fts.category_primary IN ({placeholders})')
                params.extend(category_filter)
            query = f"\n                SELECT\n                    fts.memory_id, fts.memory_type, fts.category_primary,\n                    CASE\n                        WHEN fts.memory_type = 'short_term' THEN st.processed_data\n                        WHEN fts.memory_type = 'long_term' THEN lt.processed_data\n                    END as processed_data,\n                    CASE\n                        WHEN fts.memory_type = 'short_term' THEN st.importance_score\n                        WHEN fts.memory_type = 'long_term' THEN lt.importance_score\n                        ELSE 0.5\n                    END as importance_score,\n                    CASE\n                        WHEN fts.memory_type = 'short_term' THEN st.created_at\n                        WHEN fts.memory_type = 'long_term' THEN lt.created_at\n                    END as created_at,\n                    fts.summary,\n                    rank\n                FROM memory_search_fts fts\n                LEFT JOIN short_term_memory st ON fts.memory_id = st.memory_id AND fts.memory_type = 'short_term'\n                LEFT JOIN long_term_memory lt ON fts.memory_id = lt.memory_id AND fts.memory_type = 'long_term'\n                WHERE {' AND '.join(where_conditions)}\n                ORDER BY rank, importance_score DESC\n                {self.LIMIT_SYNTAX[self.dialect]}\n            "
        elif self.dialect == DatabaseDialect.POSTGRESQL:
            where_conditions.append("(to_tsvector('english', st.searchable_content) @@ plainto_tsquery('english', %s) OR to_tsvector('english', lt.searchable_content) @@ plainto_tsquery('english', %s))")
            params.extend([query_text, query_text])
            where_conditions.append('(st.namespace = %s OR lt.namespace = %s)')
            params.extend([namespace, namespace])
            if category_filter:
                placeholders = ','.join(['%s'] * len(category_filter))
                where_conditions.append(f'(st.category_primary IN ({placeholders}) OR lt.category_primary IN ({placeholders}))')
                params.extend(category_filter * 2)
            query = f"\n                SELECT DISTINCT\n                    COALESCE(st.memory_id, lt.memory_id) as memory_id,\n                    CASE WHEN st.memory_id IS NOT NULL THEN 'short_term' ELSE 'long_term' END as memory_type,\n                    COALESCE(st.category_primary, lt.category_primary) as category_primary,\n                    COALESCE(st.processed_data, lt.processed_data) as processed_data,\n                    COALESCE(st.importance_score, lt.importance_score) as importance_score,\n                    COALESCE(st.created_at, lt.created_at) as created_at,\n                    COALESCE(st.summary, lt.summary) as summary,\n                    ts_rank(COALESCE(to_tsvector('english', st.searchable_content), to_tsvector('english', lt.searchable_content)), plainto_tsquery('english', %s)) as rank\n                FROM short_term_memory st\n                FULL OUTER JOIN long_term_memory lt ON FALSE  -- Force separate processing\n                WHERE {' AND '.join(where_conditions)}\n                ORDER BY rank DESC, importance_score DESC\n                {self.LIMIT_SYNTAX[self.dialect]}\n            "
            params.append(query_text)
        elif self.dialect == DatabaseDialect.MYSQL:
            where_conditions.append('(MATCH(st.searchable_content) AGAINST(%s IN BOOLEAN MODE) OR MATCH(lt.searchable_content) AGAINST(%s IN BOOLEAN MODE))')
            params.extend([query_text, query_text])
            where_conditions.append('(st.namespace = %s OR lt.namespace = %s)')
            params.extend([namespace, namespace])
            if category_filter:
                placeholders = ','.join(['%s'] * len(category_filter))
                where_conditions.append(f'(st.category_primary IN ({placeholders}) OR lt.category_primary IN ({placeholders}))')
                params.extend(category_filter * 2)
            query = f"\n                SELECT\n                    COALESCE(st.memory_id, lt.memory_id) as memory_id,\n                    CASE WHEN st.memory_id IS NOT NULL THEN 'short_term' ELSE 'long_term' END as memory_type,\n                    COALESCE(st.category_primary, lt.category_primary) as category_primary,\n                    COALESCE(st.processed_data, lt.processed_data) as processed_data,\n                    COALESCE(st.importance_score, lt.importance_score) as importance_score,\n                    COALESCE(st.created_at, lt.created_at) as created_at,\n                    COALESCE(st.summary, lt.summary) as summary,\n                    GREATEST(\n                        COALESCE(MATCH(st.searchable_content) AGAINST(%s IN BOOLEAN MODE), 0),\n                        COALESCE(MATCH(lt.searchable_content) AGAINST(%s IN BOOLEAN MODE), 0)\n                    ) as rank\n                FROM short_term_memory st\n                LEFT JOIN long_term_memory lt ON FALSE  -- Force UNION behavior\n                UNION ALL\n                SELECT\n                    lt.memory_id,\n                    'long_term' as memory_type,\n                    lt.category_primary,\n                    lt.processed_data,\n                    lt.importance_score,\n                    lt.created_at,\n                    lt.summary,\n                    MATCH(lt.searchable_content) AGAINST(%s IN BOOLEAN MODE) as rank\n                FROM long_term_memory lt\n                WHERE {' AND '.join(where_conditions)}\n                ORDER BY rank DESC, importance_score DESC\n                {self.LIMIT_SYNTAX[self.dialect]}\n            "
            params.extend([query_text, query_text, query_text])
        params.append(limit)
        return (query, params)
    def _get_primary_key_column(self, columns: list[str]) -> str | None:
        pk_candidates = ['id', 'memory_id', 'chat_id', 'entity_id', 'relationship_id', 'rule_id']
        for candidate in pk_candidates:
